entries[111736] = { ["name"] = "Garrison Records", ["text"] = "Quest Item\n\"Various ledgers, plans, and notes of supplies moving in and out of the garrison.\"" }
entries[111783] = { ["name"] = "Irontree Bow", ["text"] = "Binds when equipped\nRanged Bow\nSocket Bonus: +18 Stamina, +12 Dodge, and +12 Armor\nSell Price:" }
entries[111808] = { ["name"] = "Footman Longsword", ["text"] = "Quest Item\n\"A footman is only as good as his sword.\"" }
entries[111809] = { ["name"] = "Thunderbrew Keg", ["text"] = "Quest Item\n\"Absolutely necessary for any war effort.\"" }
entries[111810] = { ["name"] = "Barracks, Level 1", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nUse: Provides the plans needed to build a Barracks building in your Garrison.\nSell Price:" }
entries[111812] = { ["name"] = "Alchemy Lab, Level 1", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nUse: Provides the plans needed to build an Alchemy Lab building in your Garrison.\n\nLevel 1\nAllows the production of Alchemy items and work orders.\n\nLevel 2\nAllows followers with the Alchemy trait to work here, granting a unique bonus. Also allows up to 14 work orders at one time.\n\nLevel 3\nUnlocks Alchemy missions, and allows up to 21 work orders at one time.\nSell Price:" }
entries[111813] = { ["name"] = "The Forge, Level 1", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nUse: Provides the plans needed to build the Forge building in your Garrison.\n\nLevel 1\nAllows the production of Blacksmithing items and work orders.\n\nLevel 2\nAllows followers with the Blacksmithing trait to work here, granting a unique bonus. Also allows up to 14 work orders at one time.\n\nLevel 3\nUnlocks Blacksmithing missions, and allows up to 21 work orders at one time.\nSell Price:" }
entries[111814] = { ["name"] = "Gem Boutique, Level 1", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nUse: Provides the plans needed to build a Gem Boutique building in your Garrison.\n\nLevel 1\nAllows the production of Jewelcrafting items and work orders.\n\nLevel 2\nAllows followers with the Jewelcrafting trait to work here, granting a unique bonus. Also allows up to 14 work orders at one time.\n\nLevel 3\nUnlocks Jewelcrafting missions, and allows up to 21 work orders at one time.\nSell Price:" }
entries[111815] = { ["name"] = "Scribe's Quarters, Level 1", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nUse: Provides the plans needed to build a Scribe's Quarters building in your Garrison.\n\nLevel 1\nAllows the production of Inscription items and work orders.\n\nLevel 2\nAllows followers with the Inscription trait to work here, granting a unique bonus. Also allows up to 14 work orders at one time.\n\nLevel 3\nUnlocks Inscription missions, and allows up to 21 work orders at one time.\nSell Price:" }
entries[111816] = { ["name"] = "Tailoring Emporium, Level 1", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nUse: Provides the plans needed to build a Tailoring Emporium building in your Garrison.\n\nLevel 1\nAllows the production of Tailoring items and work orders.\n\nLevel 2\nAllows followers with the Tailoring trait to work here, granting a unique bonus. Also allows up to 14 work orders at one time.\n\nLevel 3\nUnlocks Tailoring missions, and allows up to 21 work orders at one time.\nSell Price:" }
entries[111817] = { ["name"] = "Enchanter's Study, Level 1", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nUse: Provides the plans needed to build an Enchanter's Study building in your Garrison.\n\nLevel 1\nAllows the production of Enchanting items and allows non-Enchanters to disenchant items. Also allows work orders.\n\nLevel 2\nAllows followers with the Enchanting trait to work here, granting a unique bonus. Also allows up to 14 work orders at one time.\n\nLevel 3\nUnlocks Enchanting missions, and allows up to 21 work orders at one time.\nSell Price:" }
entries[111818] = { ["name"] = "The Tannery, Level 1", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nUse: Provides the plans needed to build a Tannery building in your Garrison.\n\nLevel 1\nAllows the production of Leatherworking items and work orders.\n\nLevel 2\nAllows followers with the Leatherworking trait to work here, granting a unique bonus. Also allows up to 14 work orders at one time.\n\nLevel 3\nUnlocks Leatherworking missions, and allows up to 21 work orders at one time.\nSell Price:" }
entries[111819] = { ["name"] = "S.N.U.R.F. Gun", ["text"] = "Binds when used\nUse: Makes another player appear less menacing. (1 Min Cooldown)\nSell Price:" }
entries[111820] = { ["name"] = "Swapblaster", ["text"] = "Binds when used\nUse: Swaps your location with another party member. Cannot be used in combat. (1 Min Cooldown)\n\"Warning: Swapping with someone using a Neural Silencer is highly dangerous.\"\nSell Price:" }
entries[111821] = { ["name"] = "Blingtron 5000", ["text"] = "Binds when picked up\nToy\nUse: Assembles the upgraded Blingtron 5000, a savage, yet generous, robot. While he will give out gifts to players once per day, he will also fight other Blingtron units to the death. (4 Hrs Cooldown)\nRequires Draenor Engineering (1)" }
entries[111842] = { ["name"] = "Star Root Tuber", ["text"] = "Ashran\nBinds when picked up\nUnique (20)\nUse: Restores 32 health and reduces damage taken by 40% for 10 sec. Can only be used in Ashran. (3 Min Cooldown)" }
entries[111845] = { ["name"] = "Snapdragon Frond", ["text"] = "Quest Item\n\"Renowned for its medicinal powers when extracted properly.\"" }
entries[111846] = { ["name"] = "Riverhopper Eye", ["text"] = "Quest Item\n\"Used by some alchemists to empower their creations.\"" }
entries[111847] = { ["name"] = "Prowler Blood", ["text"] = "Quest Item\n\"Added into elixirs as a coagulant.\"" }
entries[111849] = { ["name"] = "Ninjanite Bar", ["text"] = "Crafting Reagent\nSell Price:" }
entries[111850] = { ["name"] = "Feather of Syth", ["text"] = "Quest Item\n\"While devotees of Rukhmar prefer cremation, the outcasts have taken to darker last rites.\"" }
entries[111860] = { ["name"] = "Alchemist's Cauldron", ["text"] = "Binds when picked up\n\"Yields Metamorphic Crystals and Alchemical Catalysts.\"\n<Right Click to Open>" }
entries[111863] = { ["name"] = "Goldmane's Cage Key", ["text"] = "Binds when picked up\nUnique\n\"This key seems similar in construction to the cage on top of the tower at Ironfist Harbor.\"" }
entries[111866] = { ["name"] = "Royal Peacock", ["text"] = "Binds when picked up\nUse: Teaches you how to summon this companion.\nRight Click to summon and dismiss your Royal Peachick.\nRequires level 1 to 80 ( 80)" }
entries[111867] = { ["name"] = "Alchemy Lab Cauldron", ["text"] = "Binds when picked up\n\"The bubling brew inside contains Metamorphic Crystals and Alchemical Catalysts.\"" }
entries[111874] = { ["name"] = "Earthen Core", ["text"] = "Quest Item\n\"The mineral-rich nucleus of an earth elemental.\"" }
entries[111884] = { ["name"] = "Shadowstalker Ribs", ["text"] = "Quest Item\n\"Arsenio Zerep will probably be interested in these.\"" }
entries[111885] = { ["name"] = "Gloomshade Spore", ["text"] = "Quest Item\n\"Rumor has it podlings are extremely allergic to these spores.\"" }
entries[111888] = { ["name"] = "Gulper Leg", ["text"] = "Quest Item\n\"It's like a tiny little chicken leg... made of frog meat.\"" }
entries[111891] = { ["name"] = "Nagrand Antiquity", ["text"] = "Quest Item" }
entries[111892] = { ["name"] = "The Saga of Terokk", ["text"] = "Quest Item\n\"A ribbon marks the chapter detailing Terokk's exile. Copious notes have been scrawled into the margins. All occurrences of \"Anzu\" in the text have been circled.\"" }
entries[111905] = { ["name"] = "Irridium Dust", ["text"] = "Quest Item\n\"It faintly sparkles in the light.\"" }
entries[111906] = { ["name"] = "Jovite Ore", ["text"] = "Quest Item\n\"Stones of this ore stay cold for a remarkably long time.\"" }
entries[111907] = { ["name"] = "Drudgeboat Salvage", ["text"] = "Quest Item\n\"Though soggy, the supplies in this crate could prove essential to the support of the garrison.\"" }
entries[111908] = { ["name"] = "Draenei Bucket", ["text"] = "Quest Item\nUse: Throw a bucket of water to douse fires around Squiggy in Arbor Glen." }
entries[111909] = { ["name"] = "Bow of the Iron Wolf", ["text"] = "Binds when picked up\nRanged Bow\n8 - 11 Damage Speed 3.00\n(3.2 damage per second)\n+4 Agility\n+7 Stamina\n+ 5 Critical Strike\n+ 4 Haste\nDurability 100 / 100\nSell Price:" }
entries[111910] = { ["name"] = "Goren Gas Extractor", ["text"] = "Quest Item\nUnique\nUse: Use on a dead Glowgullet Shardshedder or Glowgullet Devourer to extract gas samples. (5 Sec Cooldown)" }
