entries[111917] = { ["name"] = "Frostwolf Arrow-Swallower", ["text"] = "Binds when picked up\nOff Hand Shield\n48 Armor\n+2 Strength\n+7 Intellect\n+3 Stamina\n+ 2 Haste\n+ 2 Mastery\nDurability 85 / 85\nSell Price:" }
entries[111918] = { ["name"] = "Frostwolf Spiritguard Shield", ["text"] = "Binds when picked up\nOff Hand Shield\n48 Armor\n+2 Strength\n+7 Intellect\n+3 Stamina\n+ 2 Critical Strike\n+ 2 Haste\nDurability 85 / 85\nSell Price:" }
entries[111921] = { ["name"] = "Draenor Engineering", ["text"] = "Binds when picked up\nUnique\nUse: Learn the secrets of Draenor Engineering and a number of recipes.\nRequires Engineering (1)" }
entries[111922] = { ["name"] = "Draenor Enchanting", ["text"] = "Binds when picked up\nUnique\nUse: Learn the secrets of Draenor Enchanting and a number of recipes.\nRequires Enchanting (1)\n\"An introduction to the secrets of the enchanting of Draenor.\"" }
entries[111923] = { ["name"] = "Draenor Inscription", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you Draenor Inscription and a number of recipes.\nRequires Inscription (1)\n\"An introduction to the secrets of the inscription of Draenor.\"" }
entries[111924] = { ["name"] = "Gnomish Gearworks, Level 1", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nRequires any Alliance race\nUse: Provides the plans needed to build a Gnomish Gearworks building in your Garrison.\n\nLevel 1\nUnlocks a personal engineer that creates a powerful invention each day. Exceptional work!\n\nLevel 2\nYour engineer gains access to five new and amazing devices.\n\nLevel 3\nAllows the creation of a siege vehicle once per day. Drive it to victory in Draenor!\nSell Price:" }
entries[111925] = { ["name"] = "Engineering Supplies", ["text"] = "Binds when picked up\nUnique\nRequires Engineering (1)\n\"Contains bottled elements and gearspring parts.\"" }
entries[111926] = { ["name"] = "Codex of Ascension", ["text"] = "Ashran\nBinds when picked up\nUnique (5)\nClasses: Priest\nUse: Teaches you the spell: Ascension. Lasts for 1 hour. Can only be used in Ashran." }
entries[111927] = { ["name"] = "Fishing Shack, Level 2", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nUse: Provides the plans needed to upgrade your Fishing Shack building to level 2.\n\nLevel 1\nAllows small Draenor fish to be caught in garrison waters and provides access to daily Fishing quests.\n\nLevel 2\nAllows medium Draenor fish to be caught in garrison waters.\n\nLevel 3\nAllows enormous Draenor fish to be caught in garrison waters. Also grants you a chance to catch a unique fish that can be used to lure mysterious creatures onto the shore.\nRequires Fishing Shack\nSell Price:" }
entries[111928] = { ["name"] = "Fishing Shack, Level 3", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nUse: Provides the plans needed to upgrade your Fishing Shack building to level 3.\n\nLevel 1\nAllows small Draenor fish to be caught in garrison waters and provides access to daily Fishing quests.\n\nLevel 2\nAllows medium Draenor fish to be caught in garrison waters.\n\nLevel 3\nAllows enormous Draenor fish to be caught in garrison waters. Also grants you a chance to catch a unique fish that can be used to lure mysterious creatures onto the shore.\nRequires Achievement: Draenor Angler\nSell Price:" }
entries[111929] = { ["name"] = "Alchemy Lab, Level 2", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nUse: Provides the plans needed to upgrade your Alchemy Lab building to level 2.\n\nLevel 1\nAllows the production of Alchemy items and work orders.\n\nLevel 2\nAllows followers with the Alchemy trait to work here, granting a unique bonus. Also allows up to 14 work orders at one time.\n\nLevel 3\nUnlocks Alchemy missions, and allows up to 21 work orders at one time.\nRequires Talador Outpost questline or level 30.\nSell Price:" }
entries[111930] = { ["name"] = "Alchemy Lab, Level 3", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nUse: Provides the plans needed to upgrade your Alchemy Lab building to level 3.\n\nLevel 1\nAllows the production of Alchemy items and work orders.\n\nLevel 2\nAllows followers with the Alchemy trait to work here, granting a unique bonus. Also allows up to 14 work orders at one time.\n\nLevel 3\nUnlocks Alchemy missions, and allows up to 21 work orders at one time.\nRequires Achievement: Working More Orders\nSell Price:" }
entries[111931] = { ["name"] = "Wrenchwrecker's Inventory Report", ["text"] = "Quest Item\n\"A detailed list of construction materials with very colorful wording on the need for additional lumber.\"" }
entries[111933] = { ["name"] = "Lady Sena's Stash of Stone", ["text"] = "Quest Item\n\"These stacks of stone have been arranged in order of color and boldness.\"" }
entries[111934] = { ["name"] = "Ravager Grub", ["text"] = "Quest Item\n\"Squirmy.\"" }
entries[111937] = { ["name"] = "Lunarblossom", ["text"] = "Quest Item\n\"A beautiful flower, it shimmers under the moonlight.\"" }
entries[111938] = { ["name"] = "Lantresor's Blade", ["text"] = "Quest Item\nUnique\n\"As sharp a blade as you've ever seen.\"" }
entries[111947] = { ["name"] = "Blademaster's Banner", ["text"] = "Quest Item\n\"It's cumbersome. Hard to believe it doesn't affect the blademaster's ability to fight.\"" }
entries[111948] = { ["name"] = "Gruuk's Evil Eye", ["text"] = "Binds when picked up\nTrinket\n+ 6 Haste\nEquip: Each time your attacks hit, you have a chance to gain 50 critical strike for 20 sec. (15% chance, 115 sec cooldown) (Proc chance: 15%, 1.917m cooldown)\nSell Price:" }
entries[111951] = { ["name"] = "Alchemy Lab Cauldron - Transmutation", ["text"] = "Binds when picked up\n\"Produces a greater number of Metamorphic Crystals.\"" }
entries[111952] = { ["name"] = "Alchemy Lab Cauldron - Elixir", ["text"] = "Binds when picked up\n\"Produces a greater number of Alchemical Catalysts.\"" }
entries[111953] = { ["name"] = "Bat-Leather Breeches", ["text"] = "Binds when picked up\nLegs Leather\n7 Armor\n+4 [Agility or Intellect]\n+7 Stamina\n+ 4 Versatility\n+ 4 Mastery\nDurability 100 / 100\nSell Price:" }
entries[111955] = { ["name"] = "Skog's Drape", ["text"] = "Binds when picked up\nBack\n3 Armor\n+2 Strength\n+4 Stamina\n+ 3 Critical Strike\n+ 2 Haste\nSell Price:" }
entries[111956] = { ["name"] = "Barracks, Level 1", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nUse: Provides the plans needed to build a Barracks building in your Garrison." }
entries[111957] = { ["name"] = "Salvage Yard, Level 1", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nUse: Provides the plans needed to build a Salvage Yard building in your Garrison.\n\nLevel 1\nAllows Salvage to be occasionally recovered from missions.\n\nLevel 2\nIncreases your chance at recovering Salvage from missions. In addition, you may now discover follower items in Salvage.\n\nLevel 3\nGreatly increases your chance at recovering Salvage from missions.\nSell Price:" }
entries[111958] = { ["name"] = "Storehouse, Level 1", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nUse: Provides the plans needed to build a Storehouse building in your Garrison.\n\nLevel 1\nEnables access to your personal bank and increases the total number of active work orders for all buildings by 5.\n\nLevel 2\nEnables access to your guild bank.\n\nLevel 3\nEnables access to an Ethereal Trader for Void Storage and Transmogrification and increases the total number of active work orders for all buildings by 15.\nSell Price:" }
entries[111959] = { ["name"] = "Barn, Level 1", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nUse: Provides the plans needed to build a Barn building in your Garrison.\n\nLevel 1\nAllows you to capture clefthoof, elekk, wolves, and talbuk for leather and fur. Used for leatherworking and tailoring recipes.\n\nLevel 2\nAllows you to capture boars and riverbeasts for rare meats used to create the most powerful food.\n\nLevel 3\nAllows you to capture elite beasts to harvest for savage blood, used in all epic crafted armor and weapons.\nSell Price:" }
entries[111960] = { ["name"] = "Lunarfall Inn, Level 1", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nRequires any Alliance race\nUse: Provides the plans needed to build a Lunarfall Inn building in your Garrison.\n\nLevel 1\nEach day, a visitor offering a dungeon quest with generous rewards will spend the day at your inn.\n\nLevel 2\nRecruits random followers each week. You can specify traits and abilities you're especially interested in.\n\nLevel 3\nUnlocks the particularly lucrative garrison resource missions.\nSell Price:" }
entries[111961] = { ["name"] = "Lumber Mill, Level 1", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nUse: Learns the plans needed to build a Lumber Mill.\n\nThis building generates a daily shipment of garrison materials.\n\nLevel 1\nAllows you to mark small trees in Draenor for harvest. Harvested Timber can be converted to work orders for garrison supplies.\n\nLevel 2\nAllows you to mark medium trees for additional Timber.\n\nLevel 3\nAllows you to mark large trees for even more Timber.\nSell Price:" }
entries[111962] = { ["name"] = "Gladiator's Sanctum, Level 1", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nUse: Provides the plans needed to build a Gladiator's Sanctum building in your Garrison.\n\nLevel 1\nIncreases your out-of-combat regeneration in outdoor Draenor zones and allows the collection of broken bones from defeated enemy players (used for Conqueror's Tribute).\n\nLevel 2\nEnables safe fall and underwater breathing in outdoor Draenor zones. Also enables the Nemesis quest series for defeating enemy players of specific races.\n\nLevel 3\nWhile below 35% life, all damage taken is reduced by 50% in outdoor Draenor zones. Grants access to the Highmaul Coliseum gladiator tournament.\nSell Price:" }
entries[111963] = { ["name"] = "Trading Post, Level 1", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nUse: Provides the plans needed to build a Trading Post building in your Garrison.\n\nLevel 1\nA merchant shows up each day selling trade goods. Also allows the trade of crafting reagents for garrison resources.\n\nLevel 2\nGrants access to the Sha'tari Defense or Laughing Skull factions. Also unlocks the ability to acquire parts from around Draenor to build an auctioneer.\n\nLevel 3\nIncreases reputation gain in Draenor by 20%.\nSell Price:" }
entries[111964] = { ["name"] = "Dwarven Bunker, Level 1", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nRequires any Alliance race\nUse: Provides the plans needed to build a Dwarven Bunker building in your Garrison.\n\nLevel 1\nDoubles the chance for your quest rewards to get a rare or epic Bonus Upgrade, and increases the potency of the upgrade. Allows the collection of armor scraps from the orc clans of Draenor for armor transmogrification use.\n\nLevel 2\nOpens up work orders for follower weapons and armor in exchange for garrison resources. Also, new armor transmogrification items unlock.\n\nLevel 3\nGrants 1 of your 3 seals of inevitable fate (raid bonus loot roll) at no cost each week.\nSell Price:" }
entries[111965] = { ["name"] = "Mage Tower, Level 1", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nRequires any Alliance race\nUse: Provides the plans needed to build a Mage Tower building in your Garrison.\n\nLevel 1\nAllows the collection of Ogre Waystones from Ogres on Draenor. These waystones can be used to power an Ogre Waygate of your choice on Draenor. Also occasionally triggers Runes of Power during combat.\n\nLevel 2\nUnlocks access to a second Ogre Waygate for a total of 2.\n\nLevel 3\nUnlocks access to a third Ogre Waygate for a total of 3.\nSell Price:" }
entries[111966] = { ["name"] = "Dwarven Bunker, Level 2", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nRequires any Alliance race\nUse: Provides the plans needed to upgrade your Dwarven Bunker building to level 2.\n\nLevel 1\nDoubles the chance for your quest rewards to get a rare or epic Bonus Upgrade, and increases the potency of the upgrade. Allows the collection of armor scraps from the orc clans of Draenor for armor transmogrification use.\n\nLevel 2\nOpens up work orders for follower weapons and armor in exchange for garrison resources. Also, new armor transmogrification items unlock.\n\nLevel 3\nGrants 1 of your 3 seals of inevitable fate (raid bonus loot roll) at no cost each week.\nRequires Nagrand Outpost questline or level 40.\nSell Price:" }
entries[111967] = { ["name"] = "Dwarven Bunker, Level 3", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nRequires any Alliance race\nUse: Provides the plans needed to upgrade your Dwarven Bunker building to level 3.\n\nLevel 1\nDoubles the chance for your quest rewards to get a rare or epic Bonus Upgrade, and increases the potency of the upgrade. Allows the collection of armor scraps from the orc clans of Draenor for armor transmogrification use.\n\nLevel 2\nOpens up work orders for follower weapons and armor in exchange for garrison resources. Also, new armor transmogrification items unlock.\n\nLevel 3\nGrants 1 of your 3 seals of inevitable fate (raid bonus loot roll) at no cost each week.\nRequires Achievement: Filling The Ranks\nSell Price:" }
entries[111968] = { ["name"] = "Barn, Level 2", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nUse: Provides the plans needed to upgrade your Barn building to level 2.\n\nLevel 1\nAllows you to capture clefthoof, elekk, wolves, and talbuk for leather and fur. Used for leatherworking and tailoring recipes.\n\nLevel 2\nAllows you to capture boars and riverbeasts for rare meats used to create the most powerful food.\n\nLevel 3\nAllows you to capture elite beasts to harvest for savage blood, used in all epic crafted armor and weapons.\nRequires Spires of Arak Outpost questline or level 35.\nSell Price:" }
entries[111969] = { ["name"] = "Barn, Level 3", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nUse: Provides the plans needed to upgrade your Barn building to level 3.\n\nLevel 1\nAllows you to capture clefthoof, elekk, wolves, and talbuk for leather and fur. Used for leatherworking and tailoring recipes.\n\nLevel 2\nAllows you to capture boars and riverbeasts for rare meats used to create the most powerful food.\n\nLevel 3\nAllows you to capture elite beasts to harvest for savage blood, used in all epic crafted armor and weapons.\nRequires Achievement: Master Trapper\nSell Price:" }
entries[111970] = { ["name"] = "Barracks, Level 2", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nUse: Provides the plans needed to upgrade your Barracks building to level 2.\n\nLevel 1\nUnlocks patrol missions. Patrol missions have higher than normal follower experience rewards.\n\nLevel 2\nAllows a follower with the bodyguard trait to accompany you as a guardian in Draenor zones.\n\nLevel 3\nIncreases your follower limit by 5 and grants access to racial guards and banners.\nRequires Nagrand Outpost questline or level 40.\nSell Price:" }
entries[111971] = { ["name"] = "Barracks, Level 3", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nUse: Provides the plans needed to upgrade your Barracks building to level 3.\n\nLevel 1\nUnlocks patrol missions. Patrol missions have higher than normal follower experience rewards.\n\nLevel 2\nAllows a follower with the bodyguard trait to accompany you as a guardian in Draenor zones.\n\nLevel 3\nIncreases your follower limit by 5 and grants access to racial guards and banners.\nRequires Achievement: Patroling Draenor\nSell Price:" }
entries[111972] = { ["name"] = "Enchanter's Study, Level 2", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nUse: Provides the plans needed to upgrade your Enchanter's Study building to level 2.\n\nLevel 1\nAllows the production of Enchanting items and allows non-Enchanters to disenchant items. Also allows work orders.\n\nLevel 2\nAllows followers with the Enchanting trait to work here, granting a unique bonus. Also allows up to 14 work orders at one time.\n\nLevel 3\nUnlocks Enchanting missions, and allows up to 21 work orders at one time.\nRequires Talador Outpost questline or level 30.\nSell Price:" }
entries[111973] = { ["name"] = "Enchanter's Study, Level 3", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nUse: Provides the plans needed to upgrade your Enchanter's Study building to level 3.\n\nLevel 1\nAllows the production of Enchanting items and allows non-Enchanters to disenchant items. Also allows work orders.\n\nLevel 2\nAllows followers with the Enchanting trait to work here, granting a unique bonus. Also allows up to 14 work orders at one time.\n\nLevel 3\nUnlocks Enchanting missions, and allows up to 21 work orders at one time.\nRequires Achievement: Working More Orders\nSell Price:" }
entries[111974] = { ["name"] = "Gem Boutique, Level 2", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nUse: Provides the plans needed to upgrade your Gem Boutique building to level 2.\n\nLevel 1\nAllows the production of Jewelcrafting items and work orders.\n\nLevel 2\nAllows followers with the Jewelcrafting trait to work here, granting a unique bonus. Also allows up to 14 work orders at one time.\n\nLevel 3\nUnlocks Jewelcrafting missions, and allows up to 21 work orders at one time.\nRequires Talador Outpost questline or level 30.\nSell Price:" }
