entries[111980] = { ["name"] = "Gladiator's Sanctum, Level 2", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nUse: Provides the plans needed to upgrade your Gladiator's Sanctum building to level 2.\n\nLevel 1\nIncreases your out-of-combat regeneration in outdoor Draenor zones and allows the collection of broken bones from defeated enemy players (used for Conqueror's Tribute).\n\nLevel 2\nEnables safe fall and underwater breathing in outdoor Draenor zones. Also enables the Nemesis quest series for defeating enemy players of specific races.\n\nLevel 3\nWhile below 35% life, all damage taken is reduced by 50% in outdoor Draenor zones. Grants access to the Highmaul Coliseum gladiator tournament.\nRequires Spires of Arak Outpost questline or level 35.\nSell Price:" }
entries[111981] = { ["name"] = "Gladiator's Sanctum, Level 3", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nUse: Provides the plans needed to upgrade your Gladiator's Sanctum building to level 3.\n\nLevel 1\nIncreases your out-of-combat regeneration in outdoor Draenor zones and allows the collection of broken bones from defeated enemy players (used for Conqueror's Tribute).\n\nLevel 2\nEnables safe fall and underwater breathing in outdoor Draenor zones. Also enables the Nemesis quest series for defeating enemy players of specific races.\n\nLevel 3\nWhile below 35% life, all damage taken is reduced by 50% in outdoor Draenor zones. Grants access to the Highmaul Coliseum gladiator tournament.\nRequires Achievement: The Bone Collector\nSell Price:" }
entries[111982] = { ["name"] = "Storehouse, Level 2", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nUse: Provides the plans needed to upgrade your Storehouse building to level 2.\n\nLevel 1\nEnables access to your personal bank and increases the total number of active work orders for all buildings by 5.\n\nLevel 2\nEnables access to your guild bank.\n\nLevel 3\nEnables access to an Ethereal Trader for Void Storage and Transmogrification and increases the total number of active work orders for all buildings by 15.\nRequires Talador Outpost questline or level 30.\nSell Price:" }
entries[111983] = { ["name"] = "Storehouse, Level 3", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nUse: Provides the plans needed to upgrade your Storehouse building to level 3.\n\nLevel 1\nEnables access to your personal bank and increases the total number of active work orders for all buildings by 5.\n\nLevel 2\nEnables access to your guild bank.\n\nLevel 3\nEnables access to an Ethereal Trader for Void Storage and Transmogrification and increases the total number of active work orders for all buildings by 15.\nRequires Achievement: Got My Mind On My Draenor Money\nSell Price:" }
entries[111984] = { ["name"] = "Gnomish Gearworks, Level 2", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nRequires any Alliance race\nUse: Provides the plans needed to upgrade your Gnomish Gearworks building to level 2.\n\nLevel 1\nUnlocks a personal engineer that creates a powerful invention each day. Exceptional work!\n\nLevel 2\nYour engineer gains access to five new and amazing devices.\n\nLevel 3\nAllows the creation of a siege vehicle once per day. Drive it to victory in Draenor!\nRequires Nagrand Outpost questline or level 40.\nSell Price:" }
entries[111985] = { ["name"] = "Gnomish Gearworks, Level 3", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nRequires any Alliance race\nUse: Provides the plans needed to upgrade your Gnomish Gearworks building to level 3.\n\nLevel 1\nUnlocks a personal engineer that creates a powerful invention each day. Exceptional work!\n\nLevel 2\nYour engineer gains access to five new and amazing devices.\n\nLevel 3\nAllows the creation of a siege vehicle once per day. Drive it to victory in Draenor!\nRequires Achievement: Terrific Technology\nSell Price:" }
entries[111986] = { ["name"] = "Trading Post, Level 2", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nUse: Provides the plans needed to upgrade your Trading Post building to level 2.\n\nLevel 1\nA merchant shows up each day selling trade goods. Also allows the trade of crafting reagents for garrison resources.\n\nLevel 2\nGrants access to the Sha'tari Defense or Laughing Skull factions. Also unlocks the ability to acquire parts from around Draenor to build an auctioneer.\n\nLevel 3\nIncreases reputation gain in Draenor by 20%.\nRequires Spires of Arak Outpost questline or level 35.\nSell Price:" }
entries[111987] = { ["name"] = "Trading Post, Level 3", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nUse: Provides the plans needed to upgrade your Trading Post building to level 3.\n\nLevel 1\nA merchant shows up each day selling trade goods. Also allows the trade of crafting reagents for garrison resources.\n\nLevel 2\nGrants access to the Sha'tari Defense or Laughing Skull factions. Also unlocks the ability to acquire parts from around Draenor to build an auctioneer.\n\nLevel 3\nIncreases reputation gain in Draenor by 20%.\nRequires Achievement: Savage Friends\nSell Price:" }
