entries[111993] = { ["name"] = "Tailoring Emporium, Level 3", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nUse: Provides the plans needed to upgrade your Tailoring Emporium building to level 3.\n\nLevel 1\nAllows the production of Tailoring items and work orders.\n\nLevel 2\nAllows followers with the Tailoring trait to work here, granting a unique bonus. Also allows up to 14 work orders at one time.\n\nLevel 3\nUnlocks Tailoring missions, and allows up to 21 work orders at one time.\nRequires Achievement: Working More Orders\nSell Price:" }
entries[111996] = { ["name"] = "Lunarfall Excavation, Level 3", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nRequires any Alliance race\nUse: Provides the plans needed to upgrade your Lunarfall Excavation to level 3.\n\nLevel 1\nAllows players to mine Draenic Stone from mineral nodes in Draenor. Draenic Stone can be converted to work orders for Draenor minerals.\n\nLevel 2\nAllows followers with the Mining trait to work here, granting a unique bonus. Also opens a new mineshaft, granting access to additional mining nodes and allows up to 14 work orders at one time.\n\nLevel 3\nA final mineshaft allows access to rich mining nodes. In addition, garrison guards will patrol your mine, keeping it clear of hostile goren. Also allows up to 21 work orders at one time.\nRequires Achievement: Draenic Stone Collector\nSell Price:" }
entries[111997] = { ["name"] = "Herb Garden, Level 3", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nUse: Provides the plans needed to upgrade your Herb Garden to level 3.\n\nLevel 1\nGrows Draenic Seeds into herbs each day and herbalism nodes are available in the garden.\n\nLevel 2\nAllows followers with the Herbalism trait to work here, granting a unique bonus. Also increases the amount of herbs that can be harvested at the garden and allows up to 14 work orders at one time.\n\nLevel 3\nGrow a unique Draenor fruit tree in your garden that grants food buffs. Also allows up to 21 work orders at one time.\nRequires Achievement: Draenic Seed Collector\nSell Price:" }
entries[111998] = { ["name"] = "Menagerie, Level 2", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nUse: Provides the plans needed to upgrade your Menagerie building to level 2.\n\nLevel 1\nAttracts elite pets you can battle for rewards. Also lets 5 of your battle pets hang out in your garrison.\n\nLevel 2\nIncreases your trap chance and reduces the cooldown of Revive Battle Pets while in Draenor. Up to 10 of your pets can now hang out in your garrison.\n\nLevel 3\nUnlocks a pet battle daily with unique pet rewards.\nRequires Pet Menagerie\nSell Price:" }
entries[111999] = { ["name"] = "Menagerie, Level 3", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nUse: Provides the plans needed to upgrade your Menagerie building to level 3.\n\nLevel 1\nAttracts elite pets you can battle for rewards. Also lets 5 of your battle pets hang out in your garrison.\n\nLevel 2\nIncreases your trap chance and reduces the cooldown of Revive Battle Pets while in Draenor. Up to 10 of your pets can now hang out in your garrison.\n\nLevel 3\nUnlocks a pet battle daily with unique pet rewards.\nRequires Achievement: Draenic Pet Battler\nSell Price:" }
entries[112001] = { ["name"] = "Stables, Level 1", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nUse: Provides the plans needed to build a Stables building in your Garrison.\n\nLevel 1\nEnables the capture and training of special mounts on Draenor. Also allows you remain mounted while interacting with objects in outdoor Draenor zones.\n\nLevel 2\nYou will no longer get dazed by enemies while riding mounts in outdoor Draenor zones.\n\nLevel 3\nIncreases mount speed in Draenor by 20%.\nSell Price:" }
entries[112002] = { ["name"] = "Stables, Level 2", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nUse: Provides the plans needed to upgrade your Stables building to level 2.\n\nLevel 1\nEnables the capture and training of special mounts on Draenor. Also allows you remain mounted while interacting with objects in outdoor Draenor zones.\n\nLevel 2\nYou will no longer get dazed by enemies while riding mounts in outdoor Draenor zones.\n\nLevel 3\nIncreases mount speed in Draenor by 20%.\nRequires Nagrand Outpost questline or level 40.\nSell Price:" }
