entries[112005] = { ["name"] = "The Jailer's Libram", ["text"] = "Ashran\nBinds when picked up\nUnique (5)\nClasses: Paladin\nUse: Teaches you the spell: Jailer's Judgment. Lasts for 1 hour. Can only be used while in Ashran." }
entries[112006] = { ["name"] = "Gordunni \"Toothpick\"", ["text"] = "Quest Item\n\"Caked grime covers the blade.\"" }
entries[112015] = { ["name"] = "Forsaken Brains", ["text"] = "Racial PvP Token\nAshran\nBinds when picked up\n\"Still warm and pulsating.\"" }
entries[112020] = { ["name"] = "Garrison Blueprints", ["text"] = "Quest Item\n\"There's a hole through the middle, but they're still intact.\"" }
entries[112021] = { ["name"] = "Blueprints: Workshop", ["text"] = "Quest Item\n\"There's a hole through the middle, but they're still intact.\"" }
entries[112022] = { ["name"] = "Recipe: Mighty Shadow Protection Potion", ["text"] = "Binds when picked up\nUse: Teaches you how to make a Mighty Shadow Protection Potion.\nRequires Alchemy (400)\nRequires Alchemical Catalyst - Lotus\nSell Price:\nMighty Shadow Protection Potion\nUse: Absorbs 1134 shadow damage. Lasts 2 min. (5 Min Cooldown)\nSell Price:\nRequires Crystallized Life (2), Crystal Vial" }
entries[112023] = { ["name"] = "Recipe: Draenic Philosopher's Stone", ["text"] = "Binds when picked up\nUse: Teaches you how to make a Draenic Philosopher's Stone.\nRequires Draenor Alchemy (1)\nSell Price:\nDraenic Philosopher's Stone\nBinds when picked up\nUnique-Equipped: Alchemist Stone (1)\nTrinket\n+ 4 Mastery\nEquip: When you heal or deal damage you have a chance to increase your Strength, Agility, or Intellect by 23 for 15 sec. Your highest stat is always chosen. (Proc chance: 35%, 55s cooldown)\nEquip: Increases the effect that healing and mana potions have on the wearer by 40%. This effect does not stack.\nRequires Draenor Alchemy (1)\n\"Can be used for transmutations in place of a Philosopher's Stone.\"\nSell Price:\nRequires Alchemical Catalyst (5), True Iron Ore" }
entries[112024] = { ["name"] = "Recipe: Draenic Agility Flask", ["text"] = "Binds when picked up\nUse: Teaches you how to make a Draenic Agility Flask.\nRequires Draenor Alchemy (1)\nSell Price:\nDraenic Agility Flask\nUse: Increases Agililty by 31 for 1 hour. Counts as both a Battle and Guardian elixir. This effect persists through death. (3 Sec Cooldown)\nSell Price:\nRequires Crystal Vial , Fireweed (4), Starflower (4)" }
entries[112026] = { ["name"] = "Recipe: Draenic Intellect Flask", ["text"] = "Binds when picked up\nUse: Teaches you how to make a Draenic Intellect Flask.\nRequires Draenor Alchemy (1)\nSell Price:\nDraenic Intellect Flask\nUse: Increases Intellect by 31 for 1 hour. Counts as both a Battle and Guardian elixir. This effect persists through death. (3 Sec Cooldown)\nSell Price:\nRequires Crystal Vial , Starflower (4), Talador Orchid (4)" }
