entries[112042] = { ["name"] = "Recipe: Draenic Channeled Mana Potion", ["text"] = "Binds when picked up\nUse: Teaches you how to make a Draenic Channeled Mana Potion.\nRequires Draenor Alchemy (1)\nSell Price:\nDraenic Channeled Mana Potion\nUse: Puts the imbiber in an elevated state of focus where they can restore up to ( 255 * 10) mana over 10 sec, but they are defenseless until their focus is broken. (5 Min Cooldown)\nSell Price:\nRequires Crystal Vial , Starflower (3)" }
entries[112043] = { ["name"] = "Recipe: Draenic Mana Potion", ["text"] = "Binds when picked up\nUse: Teaches you how to make a Draenic Mana Potion.\nRequires Draenor Alchemy (1)\nSell Price:\nDraenic Mana Potion\nUse: Restores 1700 mana. (5 Min Cooldown)\nSell Price:\nRequires Crystal Vial , Gorgrond Flytrap (3)" }
