entries[112324] = { ["name"] = "Nightmarish Hitching Post", ["text"] = "Binds when picked up\nToy\nUse: Summons a nightmarish hitching post.\n\nParty members may use the post to transform their mounts into Warforged Nightmares for 20 min. (3 Min Cooldown)\nRequires Warforged Nightmare" }
entries[112326] = { ["name"] = "Warforged Nightmare", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. The capabilities of this mount depend on your Riding skill and location.\nSummons and dismisses a rideable Warforged Nightmare mount. The capabilities of this mount depend on your Riding skill and location.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"A nightmarish steed of hardened steel and vengeful spirits, this companion will follow you to the depths of the Firelands and back without complaint.\"\nIn-Game Shop" }
entries[112327] = { ["name"] = "Grinning Reaver", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. The capabilities of this mount depend on your Riding skill and location.\nSummons and dismisses a rideable Grinning Reaver mount. The capabilities of this mount depend on your Riding skill and location.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The difference between a smile and a grin is the difference between a kiss and tasting.\"\nIn-Game Shop" }
